import tarfile

# Print the _tarfile header format string if available
# tarfile uses a struct-like format. Let's look at the key method
import inspect

# The _extractattr or _create_ustar method
for name in ['TarFile', '_TarInfo', 'TarInfo']:
    obj = getattr(tarfile, name, None)
    if obj:
        try:
            src = inspect.getsource(obj)
        except:
            continue
        lines = src.split('\n')
        for i, l in enumerate(lines):
            if any(k in l.lower() for k in ['header', 'ustar', 'magic', 'ver', 'uid', 'gid', 'mode', 'mtime', 'cname', 'gname']):
                print(f"[{name}] line {i}: {l}")
                if name != 'TarInfo':
                    pass
